    doc.loc.source = {"body":"#import \"./fragments/MediaPost.gql\"\n\nquery MediaPostsWithComments(\n  $where: MediaPostWhereInput!\n  $data1: MediaPostWhereUniqueInput!\n) {\n  mediaPosts(where: $where) {\n    ...PublicPostFields\n  }\n  mediaPost(where: $data1) {\n    ...PublicPostFields\n  }\n}\n\n\nmutation MediaPostsCreate($data: MediaPostCreateInput!) {\n  createMediaPost(data: $data) {\n    ...PostFields\n  }\n}\n\nmutation MediaPostsDelete($id: MediaPostWhereUniqueInput!) {\n  deleteMediaPost(where: $id) {\n    id\n  }\n}\n\nquery MediaPostsRead(\n  $where: MediaPostWhereInput\n  $skip: Int\n  $first: Int\n  $after: String\n  $orderBy: MediaPostOrderByInput\n) {\n  mediaPosts(\n    where: $where\n    skip: $skip\n    first: $first\n    after: $after\n    orderBy: $orderBy\n  ) {\n    ...PostFields\n  }\n}\n\nquery MediaPostReadWithComments(\n  $where: MediaPostWhereInput!\n  $comments_first: Int\n  $comments_skip: Int\n  $comments_orderBy: MediaPostOrderByInput\n  $comments_where: MediaPostWhereInput) {\n  mediaPostWithComments(where: $where) {\n    ...PostFieldsCommentsWhere\n  }\n}\n\nquery PublicMediaPostsRead(\n  $where: PublicMediaPostWhereInput!\n  $skip: Int\n  $first: Int\n  $after: String\n  $orderBy: MediaPostOrderByInput\n) {\n  mediaPostsPublic(\n    data: $where\n    skip: $skip\n    first: $first\n    after: $after\n    orderBy: $orderBy\n  ) {\n    ...PublicPostFields\n  }\n}\nquery PublicMediaPostsWithComments(\n  $where: PublicMediaPostWhereInput!\n  $data1: PublicMediaPostWhereInput!\n) {\n  mediaPostsPublic(data: $where) {\n    ...PublicPostFields\n  }\n  mediaPostPublic(data: $data1) {\n    ...PublicPostFields\n  }\n}\nquery MediaPostRead($where: MediaPostWhereUniqueInput!) {\n  mediaPost(where: $where) {\n    ...PostFieldsWithComments\n  }\n}\n\nmutation MediaPostsUpdate(\n  $data: MediaPostUpdateInput!\n  $where: MediaPostWhereUniqueInput!\n) {\n  updateMediaPost(data: $data, where: $where) {\n    id\n  }\n}\n\nquery MediaFeeds($where: MediaPostWhereInput!, $first: Int, $after: String) {\n  mediaFeeds(where: $where, first: $first, after: $after) {\n    id\n    createTime\n    title\n    text\n    url\n    profiles {\n      service {\n          id\n          name\n          displayName\n          type\n          icon\n          color\n      }\n      name\n      username\n      url\n    }\n    location {\n      geojson\n    }\n  }\n}\n\nsubscription MediaFeedSubscription {\n  mediaFeed {\n    mutation\n    node {\n      ...PostFields\n    }\n    previousValues {\n      id\n    }\n  }\n}\n\nsubscription MediaPostsSubscription($where: MediaPostSubscriptionWhereInput) {\n  mediaPost(where: $where) {\n    mutation\n    node {\n      ...PostFields\n    }\n    previousValues {\n      id\n    }\n  }\n}\n\nsubscription MediaPostsCalendarSubscription($where: MediaPostSubscriptionWhereInput) {\n  mediaPost(where: $where) {\n    mutation\n    node {\n      ...PostFieldsCalendar\n    }\n    previousValues {\n      id\n    }\n  }\n}\n\nquery allMediaPostsCounts($query: String) {\n  allPosts: mediaPostsConnection(\n    where: {\n      isUserGenerated: true \n      OR: [\n        { text_contains: $query },\n        { title_contains: $query} \n      ]\n      }\n      ) {\n    aggregate {\n      count\n    }\n  }\n  publishedPosts: mediaPostsConnection(\n    where: {\n      isPublished: true,\n      isUserGenerated: true \n      OR: [\n        { text_contains: $query },\n        { title_contains: $query} \n      ]\n    }\n  ) {\n    aggregate {\n      count\n    }\n  }\n  scheduledPosts: mediaPostsConnection(\n    where: {\n      isPublished: false,\n      publishTime_not: null\n      isUserGenerated: true \n          OR: [\n        { text_contains: $query },\n        { title_contains: $query} \n      ]\n    }\n  ) {\n    aggregate {\n      count\n    }\n  }\n  draftPosts: mediaPostsConnection(\n    where: {\n      isPublished: false, \n      publishTime: null\n      isUserGenerated: true \n          OR: [\n        { text_contains: $query },\n        { title_contains: $query} \n      ]\n    }\n  ) {\n    aggregate {\n      count\n    }\n  }\n    noisePosts: mediaPostsConnection(\n      where: {\n        isUserGenerated: false,\n        isPublished: true,\n        publishTime_not: null\n            OR: [\n        {text_contains: $query },\n        { title_contains: $query} \n      ]\n      }\n    ) {\n    aggregate {\n      count\n    }\n  }\n}\n\nquery MediaPostsCounts($where: MediaPostWhereInput, $skip: Int) {\n  mediaPostsConnection(where: $where, skip: $skip) {\n    aggregate {\n      count\n    }\n  }\n}\n\nquery PublicMediaPostsCounts($where: PublicMediaPostWhereInput, $skip: Int) {\n  mediaPostsPublicConnection(data: $where, skip: $skip) {\n    aggregate {\n      count\n    }\n  }\n}\nquery MediaPostsCalendarRead(\n  $where: MediaPostWhereInput\n  $orderBy: MediaPostOrderByInput\n) {\n  mediaPosts(where: $where, orderBy: $orderBy) {\n    ...PostFieldsCalendar\n  }\n}\n","name":"GraphQL request","locationOffset":{"line":1,"column":1}};
  

