    doc.loc.source = {"body":"#import \"./fragments/PlanInject.gql\"\n\nmutation PlanInjectsCreate($data: PlanInjectCreateInput!) {\n  createPlanInject(data: $data) {\n    ...InjectFields\n  }\n}\n\nmutation PlanInjectsDelete($id: PlanInjectWhereUniqueInput!) {\n  deletePlanInject(where: $id) {\n    id\n  }\n}\n\nmutation DuplicatePlanInject($where: PlanInjectWhereUniqueInput!) {\n  duplicatePlanInject(where: $where) {\n    id\n    number\n  }\n}\n\nquery DownloadPlanInjects($where: DownloadPlanInjectInput!) {\n  downloadPlanInjects(where: $where)\n}\n\nquery PlanInjectsRead(\n  $where: PlanInjectWhereInput\n  $skip: Int\n  $first: Int\n  $after: String\n  $orderBy: PlanInjectOrderByInput\n) {\n  planInjects(\n    where: $where\n    skip: $skip\n    first: $first\n    after: $after\n    orderBy: $orderBy\n  ) {\n      ...InjectFields\n  }\n}\n\nquery PlanInjectsList(\n  $where: PlanInjectWhereInput\n  $skip: Int\n  $first: Int\n  $after: String\n  $orderBy: PlanInjectOrderByInput\n) {\n  planInjects(\n    where: $where\n    skip: $skip\n    first: $first\n    after: $after\n    orderBy: $orderBy\n  ) {\n        ...InjectList\n  }\n}\n\nquery InjectTracker(\n  $orderBy: PlanInjectOrderByInput,\n\t$trainingObjectiveId: ID) {\n  planInjects(\n    where: { \n      deletedAt: null,\n      AND: [\n        {\n          objectives_some: {\n            OR: [\n              { id: $trainingObjectiveId }\n            ]\n          }              \n        }\n      ]}\n  orderBy: $orderBy) {\n    id\n    title\n    number\n  }\n}\n\nquery MSELTracker(\n  $orderBy: PlanInjectOrderByInput,\n\t$eventName: String) {\n  planInjects(\n    where: { \n      deletedAt: null,\n      OR: [\n        {\n          events_some: {\n        OR: [\n          {name_contains: $eventName}\n        ]  \n        }\n        }\n      ]}\n  orderBy: $orderBy) {\n    ...InjectFields\n  }\n}\n\nquery PlanInjectsSearch(\n  $query: String,\n  $event: String, \n  $orderBy: PlanInjectOrderByInput, $first: Int, $skip: Int) {\n  planInjectsSearch(query: $query, orderBy: $orderBy, event: $event, first:$first, skip:$skip) {\n    ...InjectList\n  }\n  }\n\n\nquery PlanInjectRead($where: PlanInjectWhereUniqueInput!) {\n  planInject(where: $where) {\n    ...InjectFields\n  }\n}\n\nmutation PlanInjectsUpdate(\n  $data: PlanInjectUpdateInput!\n  $where: PlanInjectWhereUniqueInput!\n) {\n  updatePlanInject(data: $data, where: $where) {\n    ...InjectFields\n  }\n}\n\nsubscription PlanInjectsSubscription($where: PlanInjectSubscriptionWhereInput) {\n  planInject(where: $where) {\n    mutation\n    node {\n    ...InjectFields\n    }\n    previousValues {\n      id\n    }\n  }\n}\n\nsubscription PlanInjectsSearchSubscription($query: String, $event: String) {\n  planInjectsSearch(query: $query, event: $event) {\n    mutation\n    node {\n    ...InjectList\n    }\n    previousValues {\n      id\n    }\n  }\n}\n\nquery PlanInjectsCounts($where: PlanInjectWhereInput, $skip: Int) {\n  planInjectsConnection(where: $where, skip: $skip) {\n    aggregate {\n      count\n    }\n  }\n}\n\nquery PlanInjectsSearchCount(\n  $query: String,\n  $event: String) {\n  planInjectsSearchCount(query: $query, event: $event) {\n        aggregate {\n      count\n    }\n  }\n  }\n\nquery PlanInjectsCalendarRead(\n  $where: PlanInjectWhereInput\n  $skip: Int\n  $first: Int\n  $after: String\n  $orderBy: PlanInjectOrderByInput\n) {\n  planInjects(\n    where: $where\n    skip: $skip\n    first: $first\n    after: $after\n    orderBy: $orderBy\n  ) {\n    ...InjectCalendar\n  }\n}\n\nsubscription PlanInjectsCalendarSubscription(\n  $where: PlanInjectSubscriptionWhereInput\n) {\n  planInject(where: $where) {\n    mutation\n    node {\n    ...InjectCalendar\n    }\n    previousValues {\n      id\n    }\n  }\n}","name":"GraphQL request","locationOffset":{"line":1,"column":1}};
  

