    doc.loc.source = {"body":"#import \"@/shared/graphql/fragments/Location.gql\"\n#import \"@/plan/graphql/fragments/PlanMethod.gql\"\n#import \"@/plan/graphql/fragments/PlanInjectOwner.gql\"\n#import \"@/plan/graphql/fragments/PlanLabel.gql\"\n#import \"@/shared/graphql/fragments/MediaFile.gql\"\n#import \"./PlanMeasure.gql\"\n#import \"./PlanAssessment.gql\"\n#import \"./PlanPlatform.gql\"\n#import \"./PlanAccreditedTask.gql\"\n#import \"./PlanPriorityLevel.gql\"\n#import \"./PlanRequestedMethodType.gql\"\n#import \"./PlanTrainedMethodType.gql\"\n\nfragment InjectFields on PlanInject {\n    id\n    title\n    location { ...LocationFields }\n    description\n    mitigation\n    type\n    method { ...MethodFields }\n    number\n    owner { ...InjectOwnerFields }\n    trigger\n    response\n    responseDate\n    remarks\n    status { ...LabelFields }\n    attachments { ...FileFields }\n    deletedAt\n    createdAt\n    updatedAt\n    events { ...EventFieldsWithoutInject }\n    start: startDate\n    end: startDate\n    startDate\n    from\n    to\n    objectives {...InjectFieldsTO}\n}\n\nfragment InjectList on PlanInject {\n    id\n    title\n    location { ...LocationFields }\n    description\n    mitigation\n    type\n    method { ...MethodFields }\n    number\n    owner { ...InjectOwnerFields }\n    trigger\n    response\n    responseDate\n    remarks\n    status { ...LabelFields }\n    attachments { ...FileFields }\n    deletedAt\n    createdAt\n    updatedAt\n    events { ...InjectEventSlim }\n    start: startDate\n    end: startDate\n    startDate\n    from\n    to\n    objectives { \n      id \n      participant { ...InjectParticipantSlim } \n      platform { ...PlanTrainingObjPlatformFields }\n      jmet { ...JMETFields }\n      trainedMethodType {...TrainedMethodTypeFields}\n      measures { ...PlanMeasureFields }\n    }\n}\n\nfragment InjectEventSlim on PlanEvent {\n  id\n  name \n  color\n}\n\nfragment InjectParticipantSlim on PlanParticipant {\n    id\n    title: name\n    name\n}\n\nfragment OrgFields on PlanOrganization {\n    id\n    name\n    group\n    key\n}\n\nfragment EventFieldsWithoutInject on PlanEvent {\n    id\n    name\n    type\n    method\n    startDate\n    endDate\n    locations {id geojson geohash}\n    description\n    color\n    organization { ...OrgFields }\n    exerciseGuidance\n}\n\nfragment JMETFields on PlanJmet {\n      id\n      levelWar\n      taskNumber\n      taskTitle\n      description\n      key\n}\n\nfragment JSTPFields on PlanJointStaffTrainingPriority {\n      id\n      title\n      description\n}\n\nfragment ExerciseObjectiveFields on PlanExerciseObjective {\n  id\n  title\n  exerciseObjective\n  measurePerformance\n  measureEffectiveness\n}\n\nfragment CommandPriorityFields on PlanCommandPriority {\n    id\n    title\n    description\n}\n\nfragment InjectFieldsTO on PlanTrainingObjective {\n  id\n  platform { ...PlanTrainingObjPlatformFields }\n  jmet { ...JMETFields }\n  requestedMethod\n  trainedMethod\n  priority\n  priorityLevel { ...PlanPriorityLevelFields }\n  requestedMethodType {...RequestedMethodTypeFields}\n  trainedMethodType {...TrainedMethodTypeFields}\n  requiredRuns\n  classification\n  task\n  condition\n  standard\n  exerciseObjective { ...ExerciseObjectiveFields }\n  accreditedTask { ...TaskFields }\n  commandTrainingPriority { ...CommandPriorityFields }\n  jointStaffTrainingPriority { ...JSTPFields }\n  participant { ...PlanInjectTrainingObjParticipantFields }\n  assessments { ...PlanAssessmentFields }\n  createdAt\n  updatedAt\n  injects(where: { deletedAt: null }, orderBy: number_ASC ) { \n    id \n    number \n    title \n    description \n    mitigation \n    type \n    method {id name icon color key} \n    owner {id title key} \n    trigger \n    response \n    responseDate\n    remarks\n    status {id title description color}\n    attachments {id name secret contentType size createdAt updatedAt createTime updateTime url}\n    deletedAt\n    events {id name type method}\n    startDate\n    from\n    to\n    location {id geojson geohash} \n    }  \n  measures { ...PlanMeasureFields }\n} \n\nfragment PlanTrainingObjPlatformFields on PlanParticipantPlatform {\n  id\n  bedDown\n  audience\n  platform { id title type }\n}\n\nfragment PlanInjectTrainingObjParticipantFields on PlanParticipant {\n    id\n    title: name\n    name\n    service { ...InjectParticipantServiceFields }\n    serviceType  { ...ServiceTypeFields }\n    commandAgency { ...CommandAgencyFields }\n    homeStation\n    bedDown\n    totalAudience\n    icon\n    participantType { ...TrainingObjParticipantTypeFields }\n    planners (orderBy: isPrimary_DESC) { ...PlanTrainingObjParticipantPlannerFields }\n    fundings { ...PlanTrainingObjFundingFields }\n    platforms { ...PlanTrainingObjParticipantPlatformFields }\n}\n\nfragment PlanTrainingObjParticipantPlannerFields on PlanParticipantPlanner {\n      id\n      email\n      name\n      phoneNumber\n      isPrimary\n}\n\nfragment PlanTrainingObjParticipantPlatformFields on PlanParticipantPlatform {\n  id\n  bedDown\n  audience\n  platform { ...PlatformFields }\n}\n\nfragment TrainingObjParticipantTypeFields on PlanParticipantType {\n  id\n  title\n  key\n}\n\nfragment PlanTrainingObjPlatformFields on PlanParticipantPlatform {\n  id\n  bedDown\n  audience\n  platform { id title type }\n}\n\nfragment InjectParticipantServiceFields on PlanParticipantService {\n  id\n  title\n  key\n}\n\nfragment ServiceTypeFields on PlanParticipantServiceType {\n  id\n  title\n  key\n}\n\nfragment CommandAgencyFields on PlanParticipantCommandAgency {\n  id\n  title\n  key\n}\n\nfragment PlanTrainingObjFundingFields on PlanParticipantFundingSource {\n      id\n      primarySource\n      subSource\n      amount\n}\n\n\nfragment InjectCalendar on PlanInject {\n    id\n    title\n    type\n    number\n    responseDate\n    deletedAt\n    createdAt\n    updatedAt\n    start: startDate\n    end: startDate\n    startDate\n    status {id title description color}\n}\n","name":"GraphQL request","locationOffset":{"line":1,"column":1}};
  

    var names = {};
    function unique(defs) {
      return defs.filter(
        function(def) {
          if (def.kind !== 'FragmentDefinition') return true;
          var name = def.name.value
          if (names[name]) {
            return false;
          } else {
            names[name] = true;
            return true;
          }
        }
      )
    }
