/* harmony default export */ var WorkspaceAppsvue_type_script_lang_js = ({
  name: 'workspace-apps',
  components: {
    HelpContent: helpcontent/* default */.A
  },
  data() {
    return {
      status: {
        plan: 'ACTIVE',
        media: 'ACTIVE',
        notebook: 'ACTIVE',
        web: 'ACTIVE',
        observe: 'ACTIVE',
        map: 'ACTIVE',
        activity: 'ACTIVE',
        chat: 'ACTIVE',
        resources: 'ACTIVE',
        learn: 'ACTIVE',
        settings: 'ACTIVE',
        email: 'ACTIVE',
        command: 'ACTIVE',
        dev: 'ACTIVE'
      },
      getAppListSettingReadQuery: AppListSettings.AppListSettingRead
    };
  },
  methods: {
    getAppDescription(name) {
      switch (name) {
        case 'plan':
          return 'Design, track, and assess training exercises.';
        case 'media':
          return 'Replicate an online media environment.';
        case 'notebook':
          return 'Knowledge sharing in a collaborative environment.';
        case 'web':
          return 'Portal for training audience to view published media content.';
        case 'observe':
          return 'Record and view observations in real-time.';
        case 'map':
          return 'Visualize your training exercise on an interactive 3D map.';
        case 'activity':
          return 'Review workspace activity and operational events.';
        case 'chat':
          return 'Communicate securely with messaging and group channels';
        case 'resources':
          return 'Allocate and track resources.';
        case 'learn':
          return 'Learn with interactive gameplay and test your skills.';
        case 'settings':
          return 'Manage users, workspace settings, data, and more.';
        case 'dev':
          return 'Test innovative prototypes to aid in development.';
        case 'email':
          return 'Protect conversations using a secure email service.';
        case 'command':
          return 'Manage all exercises and identify trends.';
      }
    },
    getAppAccessNote(name) {
      switch (name) {
        case 'plan':
        case 'media':
        case 'notebook':
        case 'observe':
        case 'map':
        case 'activity':
          return 'Admin, Editor';
        case 'web':
        case 'email':
        case 'chat':
        case 'settings':
          return 'All Roles';
        case 'dev':
        case 'resources':
        case 'command':
        case 'learn':
          return 'Super';
      }
    },
    addApp(state, appName) {
      this.$apollo.mutate({
        mutation: AppListSettings.AppListSettingsCreate,
        variables: {
          data: {
            name: appName.toUpperCase(),
            status: state
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Saving...',
          type: 'is-success'
        });
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Update App: ' + error);
      });
    },
    handleChange(state, appName) {
      this.$apollo.mutate({
        mutation: AppListSettings.AppListSettingsUpdate,
        variables: {
          data: {
            status: state
          },
          where: {
            name: appName.toUpperCase()
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Saving...',
          type: 'is-success'
        });
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Update App: ' + error);
      });
    }
  }
});
