/* harmony default export */ var Event_viewvue_type_script_lang_js = ({
  name: 'event-view',
  components: {
    HelpContent: helpcontent/* default */.A
  },
  props: ['id'],
  mixins: [lightOrDark/* default */.A, dateChecks/* default */.A, file/* default */.A, mediaCheck/* default */.A, injectsDownload],
  apollo: {
    planEvent: {
      query: PlanEvents.PlanEventRead,
      variables() {
        return {
          where: {
            id: this.id
          }
        };
      },
      update(data) {
        if (data && data.planEvent) {
          return data.planEvent;
        }
      }
    }
  },
  data() {
    return {
      searchQuery: '',
      planEvent: null,
      isPaginationSimple: false,
      sortOrder: 'asc',
      perPage: '15',
      fullCreate: false,
      quickAdd: false,
      planInjectTitle: '',
      downloadInProgress: false,
      orderBy: 'startDate_ASC'
    };
  },
  methods: {
    toggleQuickAdd(value) {
      this.errors.clear();
      this.$validator.reset();
      this.planInjectTitle = '';
      this.quickAdd = value;
    },
    toggleFullCreate(value) {
      this.fullCreate = value;
    },
    onSort(field, order) {
      this.orderBy = field + '_' + order.toUpperCase();
    },
    addPlanInject() {
      let planInject = new PlanInject();
      planInject.title = this.planInjectTitle;
      planInject.events = {
        connect: {
          id: this.planEvent.id
        }
      };
      planInject = Object.assign(planInject, {});
      this.$apollo.mutate({
        mutation: PlanInjects.PlanInjectsCreate,
        variables: {
          data: planInject
        }
      }).then(response => {
        let injectNumber = response.data.createPlanInject.number;
        this.$buefy.toast.open({
          message: 'Saving...',
          type: 'is-success'
        });
        this.toggleQuickAdd(false);
        if (this.fullCreate) {
          this.editPlanInject(injectNumber);
          this.toggleFullCreate(false);
        }
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'Sorry, Inject could not be created',
          type: 'is-danger'
        });
        console.error(error);
      });
    },
    editPlanInject(number) {
      this.$router.push({
        name: 'planInjectView',
        params: {
          number: number
        },
        query: {
          from: this.$route.fullPath
        }
      });
    },
    viewPlanInject(id) {
      this.$router.push({
        name: 'view-inject',
        params: {
          id: id
        }
      });
    },
    editEvent(event) {
      this.$router.push({
        name: 'editEvent',
        params: {
          event: event,
          id: event.id,
          isEdit: true
        }
      });
    },
    deleteEvent(event) {
      // Delete Event
      this.$apollo.mutate({
        mutation: PlanEvents.PlanEventsDelete,
        variables: {
          id: {
            id: event.id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Event Deleted!',
          type: 'is-success'
        });
        this.$router.go(-1);
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Delete Event: ' + error);
      });
    },
    confirmDeleteEvent(event) {
      this.$buefy.dialog.confirm({
        title: 'Delete Event',
        message: 'Are you sure you want to do this?',
        type: 'is-danger',
        onConfirm: () => this.deleteEvent(event)
      });
    },
    confirmDeleteInject(inject) {
      this.$buefy.dialog.confirm({
        title: 'Delete Inject',
        message: 'Are you sure you want to do this?',
        type: 'is-danger',
        onConfirm: () => this.deleteInject(inject)
      });
    },
    deleteInject(inject) {
      //disconnect events
      if (inject.events) {
        this.$apollo.mutate({
          mutation: PlanInjects.PlanInjectsUpdate,
          variables: {
            data: {
              events: {
                disconnect: true
              }
            },
            where: {
              id: inject.id
            }
          }
        }).then(() => {}).catch(error => {
          this.$buefy.toast.open({
            message: 'There was an error',
            type: 'is-danger'
          });
          console.error('Inject updated: ' + error);
        });
      }

      //Disconnect Objectives
      if (inject.objectives.length > 0) {
        let obj = [];
        for (let i in inject.objectives) {
          let insideObj = {
            id: inject.objectives[i].id
          };
          obj.push(insideObj);
        }
        this.$apollo.mutate({
          mutation: PlanInjects.PlanInjectsUpdate,
          variables: {
            data: {
              objectives: {
                disconnect: obj
              }
            },
            where: {
              id: inject.id
            }
          }
        }).then(() => {}).catch(error => {
          this.$buefy.toast.open({
            message: 'There was an error',
            type: 'is-danger'
          });
          console.error('Inject updated: ' + error);
        });
      }
      this.$apollo.mutate({
        mutation: PlanInjects.PlanInjectsDelete,
        variables: {
          id: {
            id: inject.id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Inject Deleted!',
          type: 'is-success'
        });
        this.$apollo.queries.planEvent.refetch();
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Inject Deleted: ' + error);
      });
    },
    confirmRemoveInject(inject) {
      this.$buefy.dialog.confirm({
        title: 'Remove Inject',
        message: 'Are you sure you want to do this?',
        type: 'is-danger',
        onConfirm: () => this.removeInject(inject)
      });
    },
    removeInject(inject) {
      this.$apollo.mutate({
        mutation: PlanEvents.PlanEventsUpdate,
        variables: {
          data: {
            injects: {
              disconnect: {
                id: inject
              }
            }
          },
          where: {
            id: this.planEvent.id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Inject Removed!',
          type: 'is-success'
        });
        this.$apollo.queries.planEvent.refetch();
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Inject Remove: ' + error);
      });
    },
    duplicatePlanInject(injectID) {
      this.$apollo.mutate({
        mutation: PlanInjects.DuplicatePlanInject,
        variables: {
          where: {
            id: injectID
          }
        }
      }).then(response => {
        if (response && response.data) {
          let injectNumber = response.data.duplicatePlanInject.number;
          this.$buefy.toast.open({
            message: 'Duplicating...',
            type: 'is-success'
          });
          this.$router.push({
            name: 'planInjectView',
            params: {
              number: injectNumber
            },
            query: {
              from: this.$route.fullPath
            }
          });
        }
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'Sorry, Inject could not be duplicated',
          type: 'is-danger'
        });
        console.error(error);
      });
    },
    downloadEventInjects(type) {
      this.downloadInProgress = true;
      let currentDate = this.moment().format('DDMMYYYY HHmm');
      let fileName = 'MSEL ' + this.$store.state.activeWorkspace.displayName + ' ' + this.planEvent.name + ' ' + currentDate + '.' + type;
      let args = {
        where: {
          event: this.planEvent.name,
          query: this.searchQuery,
          orderBy: this.orderBy,
          fileType: type
        }
      };
      this.planInjectExportFile(type, fileName, args);
      this.downloadInProgress = false;
    }
  },
  computed: {
    filteredInjects() {
      return this.planEvent.injects.filter(injects => {
        let searchRegex = new RegExp(this.searchQuery, 'i');
        return searchRegex.test(JSON.stringify(injects));
      });
    }
  }
});
