/* harmony default export */ var exercise_interactionvue_type_script_lang_js = ({
  name: 'exercise-interaction',
  props: {
    exercise: {
      type: Object,
      default: null
    },
    open: {
      default: false
    }
  },
  data() {
    return {
      exerciseInfo: ''
    };
  },
  methods: {
    cancel() {
      this.$emit('close');
    },
    save() {
      this.$apollo.mutate({
        mutation: PlanEvents.PlanEventsUpdate,
        variables: {
          data: {
            name: this.exerciseInfo.name
          },
          where: {
            id: this.exerciseInfo.id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Saving...',
          type: 'is-success'
        });
        this.cancel();
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Exercise Name Event: ' + error);
      });
    }
  },
  watch: {
    exercise() {
      this.exerciseInfo = Object.assign({}, JSON.parse(JSON.stringify(this.exercise), this.omitTypename));
    }
  }
});
