/* harmony default export */ var assess_createvue_type_script_lang_js = ({
  name: 'PlanAssessmentCreate',
  props: {
    open: {
      default: false
    }
  },
  apollo: {
    planParticipants: {
      query: PlanParticipants.PlanParticipantsList
    },
    planTrainingObjectives: {
      query: PlanTrainingObjectives.PlanTrainingObjectivesRead,
      variables() {
        return {
          where: {
            participant: {
              id: this.selectedParticipant
            }
          }
        };
      },
      update(data) {
        if (data && data.planTrainingObjectives) {
          let trainingObjectives = JSON.parse(JSON.stringify(data.planTrainingObjectives));
          // This keeps the client side sorting from throwing an error for null values
          trainingObjectives.forEach(obj => {
            if (!obj.jmet) {
              obj.jmet = {};
            }
            if (!obj.platform) {
              obj.platform = {
                platform: {}
              };
            }
          });
          return trainingObjectives;
        }
      },
      error(error) {
        console.error(error);
      }
    }
  },
  mixins: [helpers/* default */.A],
  data() {
    return {
      selectedTrainingObj: null,
      planAssessment: {
        complete: true,
        reason: '',
        comment: ''
      },
      showTrainingObjectives: false,
      planTrainingObjectives: [],
      selectedParticipant: null
    };
  },
  methods: {
    validateBeforeSubmit() {
      this.$validator.validateAll().then(result => {
        if (result) {
          this.save();
          return;
        }
      });
    },
    save() {
      if (!this.selectedTrainingObj) {
        this.$buefy.toast.open({
          message: 'No Training Objective is selected.',
          type: 'is-danger'
        });
        return;
      } else {
        this.$apollo.mutate({
          mutation: PlanAssessments.PlanAssessmentCreate,
          variables: {
            data: {
              comment: this.planAssessment.comment,
              complete: true
            }
          }
        }).then(response => {
          // connect training objective
          this.$apollo.mutate({
            mutation: PlanTrainingObjectives.PlanTrainingObjectivesUpdate,
            variables: {
              data: {
                assessments: {
                  connect: {
                    id: response.data.createPlanAssessment.id
                  }
                }
              },
              where: {
                id: this.selectedTrainingObj.id
              }
            }
          }).then(data => {
            if (data) {
              this.close();
              this.$buefy.toast.open({
                message: 'Saving...',
                type: 'is-success'
              });
              this.$router.push({
                name: 'editassess',
                params: {
                  id: response.data.createPlanAssessment.id
                }
              });
            }
          });
        }).catch(error => {
          this.$buefy.toast.open({
            message: 'There was an error',
            type: 'is-danger'
          });
          console.error('Plan Assessment create: ' + error);
        });
      }
    },
    close() {
      this.$emit('close');
      this.errors.clear();
      this.$validator.reset();
      this.planAssessment = {
        complete: true,
        reason: '',
        comment: ''
      };
      this.selectedTrainingObj = undefined;
    }
  },
  mounted() {
    this.$apollo.queries.planTrainingObjectives.refetch();
  },
  computed: {
    disableActionButton() {
      if (this.errors && this.errors.items && this.errors.items.length > 0 || !this.selectedTrainingObj || this.selectedTrainingObj.assessments.length >= this.selectedTrainingObj.injects.length) {
        return true;
      }
    }
  }
});
