/* harmony default export */ var Collectvue_type_script_lang_js = ({
  name: 'requests-list',
  components: {
    HelpContent: helpcontent/* default */.A,
    RequestInteraction: request_interaction
  },
  apollo: {
    planFeedbackRequests: {
      query: PlanFeedbackRequests.PlanFeedbackRequestsRead,
      subscribeToMore: {
        document: PlanFeedbackRequests.PlanFeedbackRequestSubscription,
        // Mutate the previous result
        updateQuery: (previousResult, {
          subscriptionData
        }) => {
          // Here, return the new result from the previous with the new data
          let mutationIn = subscriptionData.data.planFeedbackRequest.mutation;
          let newResult;
          switch (mutationIn) {
            case 'CREATED':
              {
                newResult = {
                  planFeedbackRequests: [subscriptionData.data.planFeedbackRequest.node, ...previousResult.planFeedbackRequests]
                };
                break;
              }
            case 'DELETED':
              {
                newResult = {
                  planFeedbackRequests: [...previousResult.planFeedbackRequests.filter(obj => subscriptionData.data.planFeedbackRequest.previousValues.id !== obj.id)]
                };
                break;
              }
            case 'UPDATED':
              {
                let newPlanFeedbackRequests = JSON.parse(JSON.stringify(previousResult.planFeedbackRequests));
                let index = newPlanFeedbackRequests.findIndex(x => x.id === subscriptionData.data.planFeedbackRequest.node.id);
                newPlanFeedbackRequests[index] = subscriptionData.data.planFeedbackRequest.node;
                newResult = {
                  planFeedbackRequests: newPlanFeedbackRequests
                };
                break;
              }
            default:
              {
                throw new Error(`Unknown mutation`);
              }
          }
          return newResult;
        }
      }
    }
  },
  data() {
    return {
      edit: false,
      openDialog: false,
      selectedFeedbackRequest: null,
      isPaginated: true,
      isPaginationSimple: false,
      defaultSortDirection: 'asc',
      perPage: 15
    };
  },
  methods: {
    rowClick(row) {
      this.editFeedbackRequest(row);
    },
    closeDialog() {
      this.errors.clear();
      this.edit = false;
      this.openDialog = false;
      this.selectedFeedbackRequest = new PlanFeedbackRequest();
    },
    openCreate() {
      this.selectedFeedbackRequest = new PlanFeedbackRequest();
      this.openDialog = true;
    },
    editFeedbackRequest(request) {
      this.edit = true;
      this.selectedFeedbackRequest = request;
      this.openDialog = true;
    },
    confirmDelete(request) {
      this.$buefy.dialog.confirm({
        title: 'Delete Feedback Request',
        message: 'Are you sure you want to do this?',
        type: 'is-danger',
        onConfirm: () => this.deleteRequest(request.id)
      });
    },
    deleteRequest(id) {
      this.$apollo.mutate({
        mutation: PlanFeedbackRequests.PlanFeedbackRequestsDelete,
        variables: {
          id: {
            id: id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Request Deleted!',
          type: 'is-success'
        });
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Delete Request: ' + error);
      });
    }
  }
});
