/* harmony default export */ var customReport_interactionvue_type_script_lang_js = ({
  name: 'customReport-interaction',
  mixins: [dateChecks/* default */.A],
  props: {
    report: {
      type: Object
    },
    open: {
      default: false
    }
  },
  components: {
    DatePicker: datepicker/* default */.A
  },
  data() {
    return {
      endAfterStartCheck: null,
      sources: ['Feedback', 'Assessments'],
      reportInfo: null
    };
  },
  methods: {
    close() {
      this.$emit('close');
      this.errors.clear();
      this.$validator.reset();
    },
    async validateBeforeSubmit() {
      this.endAfterStartCheck = await this.isEndAfterStart(this.reportInfo.start, this.reportInfo.end);
      this.$validator.validateAll().then(result => {
        if (result && !this.endAfterStartCheck) {
          this.save();
          return;
        }
      });
    },
    save() {
      // Update
      this.$apollo.mutate({
        mutation: PlanCustomReports.PlanCustomReportsUpsert,
        variables: {
          update: {
            title: this.reportInfo.title,
            start: this.reportInfo.start,
            end: this.reportInfo.end,
            source: this.reportInfo.source
          },
          create: {
            title: this.reportInfo.title,
            start: this.reportInfo.start,
            end: this.reportInfo.end,
            source: this.reportInfo.source
          },
          where: {
            id: this.reportInfo.id
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Saving...',
          type: 'is-success'
        });
        this.reportInfo = new PlanCustomReport();
        this.close();
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'There was an error',
          type: 'is-danger'
        });
        console.error('Update Report: ' + error);
      });
    }
  },
  watch: {
    report() {
      this.reportInfo = Object.assign({}, this.report);
    }
  }
});
