/* harmony default export */ var notefolder_editvue_type_script_lang_js = ({
  name: 'notefolder-edit',
  props: {
    isCreateNewFolder: {
      default: true
    },
    open: {
      default: false
    },
    folder: {
      type: Object
    },
    folderType: {
      type: String
    }
  },
  components: {
    Swatches: (vue_swatches_min_default())
  },
  data() {
    return {
      noteFolder: {
        name: null,
        color: ''
      }
    };
  },
  watch: {
    open() {
      this.noteFolder = this.isCreateNewFolder === true ? {
        name: 'Untitled Folder',
        color: ''
      } : this.folder;
    }
  },
  methods: {
    close() {
      this.$emit('close');
      this.errors.clear();
      this.$validator.reset();
    },
    saveNoteFolder() {
      this.$validator.validateAll().then(result => {
        if (result) {
          let noteFolderData = {
            name: this.noteFolder.name,
            color: this.noteFolder.color
          };
          let variablesData;
          if (this.isCreateNewFolder) {
            if (this.folderType !== 'root') {
              variablesData = {
                data: {
                  folders: {
                    create: noteFolderData
                  }
                },
                where: {
                  id: this.folderType
                }
              };
              this.$apollo.mutate({
                mutation: NoteFolder.NoteFolderUpdate,
                variables: variablesData
              }).then(() => {
                this.close();
              }).catch(error => {
                console.error(error);
                this.$buefy.toast.open({
                  message: error.message,
                  type: 'is-danger'
                });
              });
            } else {
              // Create folder in root
              this.$apollo.mutate({
                mutation: NoteFolder.NoteFolderCreate,
                variables: {
                  data: noteFolderData
                }
              }).then(response => {
                if (response) {
                  this.close();
                  this.$router.push({
                    path: '/note/'
                  });
                }
              }).catch(error => {
                console.error(error);
                this.$buefy.toast.open({
                  message: error.message,
                  type: 'is-danger'
                });
              });
            }
          } else {
            this.$apollo.mutate({
              mutation: NoteFolder.NoteFolderUpdate,
              variables: {
                data: noteFolderData,
                where: {
                  id: this.noteFolder.id
                }
              }
            }).then(() => {
              this.close();
              this.$buefy.toast.open({
                message: 'Folder settings updated successfully.',
                type: 'is-success'
              });
            }).catch(error => {
              console.error(error);
              this.$buefy.toast.open({
                message: error.message,
                type: 'is-danger'
              });
            });
          }
          return;
        }
      });
    }
  }
});
