/* harmony default export */ var MapHomevue_type_script_lang_js = ({
  name: 'COPMap',
  components: {
    HelpContent: helpcontent/* default */.A
  },
  apollo: {
    mapLayers: {
      query: MapLayer.MapLayersRead
    }
  },
  data() {
    return {
      mapLayers: [],
      showDialog: false,
      mapTitle: ''
    };
  },
  methods: {
    toggleCreateMapDialog() {
      this.showDialog = !this.showDialog;
    },
    duplicateMapLayer(mapId) {
      this.$apollo.mutate({
        mutation: MapLayer.MapLayerDuplicate,
        variables: {
          where: {
            id: mapId
          }
        }
      }).then(response => {
        if (response && response.data) {
          this.$buefy.toast.open({
            message: 'Duplicate success',
            type: 'is-success'
          });
          this.$router.push({
            path: '/map/copmap/edit/' + response.data.duplicateMapLayer.id
          });
        }
      }).catch(error => {
        this.$buefy.toast.open({
          message: 'Sorry, Map Layer could not be duplicated',
          type: 'is-danger'
        });
        console.error(error);
      });
    },
    createMap() {
      this.$apollo.mutate({
        mutation: MapLayer.MapLayerCreate,
        variables: {
          data: {
            title: this.mapTitle
          }
        }
      }).then(response => {
        this.toggleCreateMapDialog();
        this.$router.push({
          path: '/map/copmap/edit/' + response.data.createMapLayer.id
        });
      }).catch(error => {
        console.error(error);
        this.$buefy.toast.open({
          message: error.message,
          type: 'is-danger'
        });
      });
    },
    editMap(mapId) {
      this.$router.push({
        name: 'copmapedit',
        params: {
          id: mapId
        }
      });
    },
    confirmMapLayerDelete(mapId) {
      this.$buefy.dialog.confirm({
        title: 'Delete Map',
        message: 'Are you sure you want to do this?',
        type: 'is-danger',
        onConfirm: () => this.deleteMapLayer(mapId)
      });
    },
    deleteMapLayer(mapId) {
      this.$apollo.mutate({
        mutation: MapLayer.MapLayerDelete,
        variables: {
          where: {
            id: mapId
          }
        }
      }).then(() => {
        this.$buefy.toast.open({
          message: 'Map Deleted',
          type: 'is-success'
        });
        this.$apollo.queries.mapLayers.refetch();
      }).catch(error => {
        console.error(error);
        this.$buefy.toast.open({
          message: error.message,
          type: 'is-danger'
        });
      });
    }
  },
  computed: {
    disableActionButton() {
      return !(this.mapTitle && this.mapTitle.length > 0);
    }
  }
});
